"G": "big rectangular archaic smoking terrible yellow vase",
"H": "thai old drinking nice green massive pyramidal clock",
"I": "glass bangladeshi old-fashioned snorkeling nice magenta prismlike canvas",
"J": "spherical little ancient walking good indigo bangladeshi jar",
}

def check(s):
    toks = s.split()
    for t in toks[:-1]:
        if t not in w2c:
            return None
    seq = parse(s)
    res = set()
    for pos in exts:
        res.add(all(pos[a] < pos[b] for a, b in zip(seq, seq[1:])))
    if len(res) != 1:
        return None
    return res.pop()

if not exts:
    print("UNSUPPORTED")
else:
    good = []
    ok = True
    detail = {}
    for k, s in opts.items():
        r = check(s)
        if r is None:
            ok = False
        detail[k] = r
        if r:
            good.append(k)
    if not ok:
        print("UNSUPPORTED")
    else:
        ans = "".join(good) if good else "K"
        print(json.dumps({"final_answer": ans,
                          "evidence": {"num_linear_extensions": len(exts),
                                       "constraints": sorted(cons),
                                       "option_valid": detail}}))
