    if all(r[a] < r[b] for a, b in cons):
        perms.append(r)

def valid(r, sentence):
    seq = cat_seq(sentence)
    ranks = [r[c] for c in seq]
    return all(ranks[i] < ranks[i + 1] for i in range(len(ranks) - 1))

result = {}
ambiguous = False
for k, s in options.items():
    vals = {valid(r, s) for r in perms}
    if len(vals) != 1:
        ambiguous = True
    result[k] = vals

if not perms:
    print("UNSUPPORTED")
elif ambiguous:
    print("UNSUPPORTED")
else:
    ans = "".join(k for k in options if result[k] == {True}) or "K"
    print(json.dumps({"final_answer": ans,
                      "evidence": {"sentences": len(sents), "constraints": len(cons),
                                   "consistent_orders": len(perms),
                                   "valid": {k: sorted(v) for k, v in result.items()}}}))
